<script setup lang="ts">import {Link,router} from '@inertiajs/vue3';import AdminLayout from '@/Layouts/AdminLayout.vue';import PageMeta from '@/Components/PageMeta.vue';import EmptyState from '@/Components/EmptyState.vue';import Pagination from '@/Components/Pagination.vue';import type {Paginated,SitePage} from '@/types';defineProps<{pages:Paginated<SitePage>}>();const activate=(page:SitePage)=>router.patch(route('admin.content.activation',page.id),{active:!page.is_published},{preserveScroll:true});</script>
<template><AdminLayout title="Contenido del sitio" eyebrow="Sitio público"><PageMeta title="Contenido del sitio" noindex/><section class="admin-content"><div class="content-toolbar"><div><p class="kicker">Páginas</p><h2>{{ pages.total }} páginas</h2></div><Link class="button button--admin" :href="route('admin.content.create')">+ Nueva página</Link></div><div class="panel table-panel"><div v-if="pages.data.length" class="table-scroll"><table><thead><tr><th>Título</th><th>Slug</th><th>Meta descripción</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="page in pages.data" :key="page.id"><td><strong>{{ page.title }}</strong></td><td><code class="code-wrap">{{ page.slug }}</code></td><td class="long-copy">{{ page.meta_description||'Sin meta descripción' }}</td><td><span :class="['catalog-state',page.is_published?'on':'off']">{{ page.is_published?'Publicada':'Borrador' }}</span></td><td><div class="row-actions"><Link class="row-action" :href="route('admin.content.edit',page.id)">Editar</Link><button class="row-action" type="button" @click="activate(page)">{{ page.is_published?'Despublicar':'Publicar' }}</button></div></td></tr></tbody></table></div><EmptyState v-else title="No hay páginas configuradas"/><Pagination :links="pages.links"/></div></section></AdminLayout></template>
